from author_library import *
cards=[]
cards.append(compact('zhuo_chi','卓齿','卓齿原是秦王麾下的战马总监，熟悉养马、驯马及王陵牧马坑工程，始终以获准称君主“大王”为荣。他与九名同伴受命试服丹药，当时剧烈腹痛，后来恢复，随后自愿殉葬，竟在地底沉睡千年后再醒。此后清醒约十年又进入长眠，睡期逐步缩短，时间对他的意义因此与普通人完全不同。他曾走出王陵，养育卓长根，因下一次昏睡将至而把孩子和良马托付马醉木；这次离开既有严守同伴秘密的理由，也留下儿子一生难解的失落。终局父子相认，已经老迈的儿子坚持留下陪他，他却知道十年陪伴不能解决两种生命节律的鸿沟，借卫斯理劝儿子离开，并准备封闭通道。他对古代君主的忠诚令人难以接受，却是本人的真实选择，不应被写成现代自由主义者的代言。卡片保留精壮身体、驯马与工程知识以及药物造成的长眠，不把长寿变成受创不死、无限行动或会炼长生药；沉睡期间的照护和与时代脱节是他无法轻易消除的代价。','《活俑》留守王陵，送别卓长根并准备封闭秘道；清醒和长眠周期仍持续','主角','守住对大王和同伴的忠诚，同时尽可能安顿儿子的余生','言行庄严，擅养马，使用古代语言与忠臣尺度理解世界','涉及君主尊严会发怒，涉及亲子则以决绝掩饰离别痛苦','长生并不让所有关系拥有同样时间，秘密和亲情必须付出取舍',[ab('养马与王陵工程知识','曾任战马总监、主持牧马坑工程，熟悉驯养及本区秘道','不知王陵全部结构；不能把巨大陵墓规模换算为本人破坏力'),ab('丹药长寿与周期休眠','服药后跨越两千年仍精壮，清醒约十年后长期昏睡，睡期逐次缩短','无法随意取消休眠；药方未知，不能传授复制，非刀枪不入')],[ev('062',285,340,'托付儿子和良马'),ev('062',3270,3333,'十人服丹由来'),ev('062',3347,3437,'休眠周期和外出成家'),ev('062',3456,3498,'父子离别及留陵选择')],profile='strong'))
rate(cards[-1],[4,0,1,8,2,5],neg=(4,2,1),tier='强',reason='精壮人体和驯马经验，长寿受强制长眠代价约束；没有战斗不死或陵墓级攻击。')
cards[-1]['baseline']['stamina']='清醒期身体精壮且进食需求低，但十年后会进入长期不可行动的昏睡；睡期由千年逐次缩短，最近一次八十年。'
cards.append(compact('zhuo_changgen','卓长根','卓长根九十三岁仍高大强健、秃顶银髯、笑声洪亮，连白老大在他面前也被叫作小白。他从小在草原长大，父亲忽然把自己托给马醉木，留下仿佛即将死去却毫无病容的谜。少年时他骑术出众，爱上豪迈的马金花，率人追寻她与马群神秘失踪的下落，多年始终不能忘情。后来他建立卓氏事业，拥有财富和得力副手，遇到金花的事却仍会急得先想找快马，忘记现代汽车。金花临终告诉他地下秘密，他护送灵柩后进入王陵，终于见到仍如壮年的父亲，也明白心上人早曾与另一古人成婚。重逢没有消除遗憾：父亲不肯离开，他想留下，又因可能引来大规模搜寻而不得不告别。终局卡保留健壮长寿的遗传倾向、骑术、事业与孩子般执拗，明确他仍在衰老并非不死。财富不自动变成军队，父亲的长眠药效也不能全量继承；他的勇敢与冲动应围绕人情展开，而不是每次都只是吼叫或炫示老资格。','《活俑》告别父亲后离开王陵，仍为年迈而健壮的卓氏负责人','主角','追寻父亲与初恋留下的谜，保全珍视的旧情','豪爽、急躁、骑术精熟，熟人面前喜欢以长辈口吻说话','亲人或金花遇险时不顾排场亲自行事，重逢后难舍离别','有权势仍须尊重他人的选择，父亲长生不代表自己不会老去',[ab('骑术和牧马经验','草原成长、年轻时领队追索，长期熟悉马匹习性','不能驯服一切异兽，古人使马群停下的特殊本领不自动属于他'),ab('强健体魄与事业组织','高龄仍有突出力量和活力，拥有大型事业及助手','仍衰老会死；组织行动必须经实际安排，不计入随身战力')],[ev('062',241,285,'年龄外形和骑术'),ev('062',1612,1689,'担忧金花与相见'),ev('062',2077,2126,'事业和坚持独行'),ev('062',3453,3483,'重逢离别及仍会衰老')],profile='strong'))
cards.append(compact('ma_jinhua','马金花','马金花是马醉木的独女，从小骑马、使枪、喝酒，豪迈强悍，面对轻佻追逐不会忍让，少年时已经以骑术和激烈反击闻名。十六岁的一次牧马之行，她与群马在草原上消失，五年后回来，却不肯向亲近的人完整说明，随后去北京求学，逐渐成为享誉世界的汉学权威。地下王陵的古籍与她在那里同秦代牧马人成婚的经历，解释了她早熟而特殊的学问来源，也说明卓长根苦守的爱情从来不是她唯一的人生。晚年她到法国，发生中风，下半身瘫痪而思路仍清醒；面对卓长根，既顽皮又有衰老后的自尊，不愿以病躯拖累他，最终交代私密往事和安葬要求后去世。卡片应保留她从草原少女到大学者的一生，不把两端简单拼成永远年轻、永远能纵马格斗的全盛形态。终局部署恢复最后生前的清醒老年身体，知识与性格可以继续演绎，青春骑术是懂得却受身体限制的经验。她有权选择爱情与秘密，也要面对隐瞒造成的困惑；不能把驯马古人的本领或丈夫长生药效加给她。','《活俑》九十一岁中风后去世；部署恢复最后生前清醒而下肢瘫痪的老年形态','主角','按自己的意志生活、保留爱情秘密，并把学问传给后来者','豪爽而自负，学识深厚仍带草原口音和顽皮神态','被追问私生活时划定边界，面对衰老则不愿让旁人只看见病弱','自己的选择不能被别人多年等待替代，知识成就也不抹去个人私情',[ab('汉学与古文献','在地下接触大量古籍，后来长期求学研究成为权威','古籍来源特殊不等于知道一切历史，学术不转化为法术'),ab('骑术与枪械的历史经验','少年时熟悉马匹及武器，能够判断有关行动','终局年老中风，下肢瘫痪，不能照搬青春战斗表现')],[ev('062',5,72,'少年经历'),ev('062',1201,1281,'归来求学和学术地位'),ev('062',1660,1780,'晚年身体、性格与死亡'),ev('062',3444,3452,'成婚与五年经历')],profile='expert',aliases=['马教授']))
cards[-1]['baseline'].update({'speed':'最后生前下半身瘫痪，移动须实际辅助；保留骑术知识不恢复青春运动能力。','stamina':'高龄且刚中风，清醒交谈也受体能限制，需要护理。'})
cards.append(compact('ma_zuimu','马醉木','马醉木是陕西大牧场的主人，来历在草原上有多种传说，连这个名字也未必是本名。他养出有名的好马，生意遍及广大地区，获得过司令名号却并不看重官衔，真正相信的是豪爽、义气和牧马人的本事。他用“养得出好马便不会是坏人”的朴素尺度判断来客，见卓齿带来百匹良马又神色凄苦，主动承诺帮助并收留卓长根。女儿金花从小大胆好胜，他会担心她对追逐者下手太重，却也让她拥有自己的行动空间。金花失踪多年又回来，他当然想知道秘密，仍选择接受她不愿说，把父女重逢放在追究之上，支持她去北京读书，亲自送行。这个牧场豪强并不是只会用枪命令人的反派，他的慷慨中也含有凭直觉认人的盲点。终局历史已故，牧场在时局中不复存在，部署恢复最后可行动的生前本人，不自动重建全盛产业。他可以在陌生场景凭手艺和待人方式赢得信任，也可能因过分相信一种经验而误判；不把好马识人的个人信念写成绝对生物测谎术。','《活俑》回忆中的已故牧场主，牧场后因时局消失；部署恢复最后可行动的生前形态','主角','经营牧场、照顾托付之人并尊重女儿走向更广阔生活','豪爽讲义气，重视养马技艺超过官衔','家人失踪时焦急，重逢后宁可暂放疑问也要使她安心','经验可以帮助识人但并非绝对标准，亲近者不愿说的事不能只靠逼问',[ab('牧场经营和识马','经营大型牧场、判断良马并组织人员照护与行路','规模为历史资源，须场景重建；马匹反应不是无误的善恶鉴定'),ab('江湖接纳与协调','凭信誉收留托孤者，安排求学与家族事务','人情网络依赖具体时代和人物，不自动跨世界有效')],[ev('062',14,34,'牧场身份和个性'),ev('062',298,340,'识马和接纳托付'),ev('062',1201,1252,'尊重女儿与支持求学'),ev('062',1332,1335,'死亡和牧场消失')],profile='investigator'))
cards.append(compact('bao_shifang','鲍士方','鲍士方是卓氏机构的副总裁之一，也是卓长根的得力助手，行事爽脆、精神旺盛，平时相信可以凭组织和实际安排解决问题。卓长根护送马金花灵柩后神秘失踪，他焦急求助，一开始只能反复说人不见了，在白素安抚后才把政府交涉、独自行路和搜索经过讲清楚。他参与安排追查，最终看到老板回来，却没有得到地下秘密的完整解释；这使他后来仍把卫斯理的活俑记述当作精彩幻想。《异宝》中，他又在陵区工作时看见雾中的奇异影像，拍下照片并带来，正好给寻找齐白提供关键线索。他愿意讨论神仙或外星人的可能，也承认自己并非相关专家，既有实干者的自信，也可能急于把工作经验套在难解现象上。终局没有说明他获得那块合金或异星通讯权限，他的价值在记录、联络和执行。卡片可让他在危机中先调动自己实际负责的资源、保存照片、复述时间地点，再随证据修正解释；不会因为担任副总裁便随身携带整个财团，也不会把一次看见异象变成超视觉天赋。','《异宝》继续作为卓氏助手工作并提供异常影像线索，未获超常装备或能力','重要配角','完成受托事务并确保老板安全，弄清亲眼所见的异常','爽快直接、工作认真，喜欢拿实际见闻讨论问题','重大失踪使他焦躁，经过追问后能恢复条理并组织协助','照片证明拍到的内容，不保证自己对现象的命名正确',[ab('组织联络与执行','担任副总裁，处理行程、政府接待和搜索协作','权限限于实际机构任务，未证明拥有独立武装'),ab('现场记录','在雾中拍摄影像并保存时间地点，提供可核线索','受拍摄角度和环境限制，不是透视、预知或外星设备控制')],[ev('062',2077,2140,'副总裁身份和求助'),ev('062',3507,3509,'获救结果与信息边界'),ev('066',2043,2093,'再次登场并带照片'),ev('066',2122,2180,'记录条件和推测')],profile='expert'))
cards.append(compact('ma_jinhua_husband','马金花的秦人丈夫','马金花的丈夫是卓齿的副手，属于同服丹药、自愿进入秦王陵的十名古人之一，姓名没有在这段记录中揭开。他与同伴经历漫长昏睡和短暂清醒，在地上时代已经多次变化后，仍依靠地下共同生活维持生存。看见卓齿曾在人间成家，他也动了追求情感的念头；一次从秘道出来遇见奔驰马群，凭极精的驯马本领止住马群，将马金花引入王陵，两人在那里成婚生活五年。自己的昏睡期到来时，金花离开，他把经过记录下来供后来醒来的卓齿知晓。终局卫斯理所见的他仍蜷缩沉睡，貌相英武却没有与访客直接交谈，不能替他编出对重逢或金花死亡的即时反应。卡片允许以明确的适配在清醒期部署，保留长生药周期与历史知识，不能默认永不再睡。其人物重点是寻求亲密关系却面对无法同步的生命节律，也需承认把陌生女子带入隐秘空间所包含的权力差距；驯服真实马群不等于支配任何动物，更不是以精神术无条件控制爱人。','《活俑》仍在周期昏睡；部署取最近可行动的清醒期并保留终局知识，须明确此为参演适配','主角','在长期隔世生活中追求亲密关系，同时维护同伴秘密','熟悉驯马，习惯记录事件让不同时醒的伙伴知情','感情与昏睡周期冲突时留下记录并接受暂别','个人的长寿不能保证伴侣等待，技艺也不代表有权替对方决定',[ab('驯马绝技','曾阻止大群奔驰的马，承继秦代牧马工作经验','只证实马群场景，未说明超自然机制或所有动物控制'),ab('服丹长寿与周期昏睡','与卓齿同属十名试药者，长时间低代谢沉睡仍活着','终局正在沉睡无法行动；不知药方，不保证抗伤不死')],[ev('062',3274,3290,'所见形态与活人状态'),ev('062',3323,3354,'十人药物共同背景'),ev('062',3444,3452,'驯马、婚姻和记录')],profile='expert'))
rate(cards[-1],[3,0,1,8,2,3],neg=(4,2,1),tier='并',reason='驯马与健康古人肉身，长寿强受周期休眠限制，清醒部署不取消代价。')
