cards.append(compact('qin_shihuang','秦王（《活俑》叙述）','这张卡记录《活俑》中由卓齿讲述的秦王，属于小说化历史人物，并不把叙述当作现实史学结论。他统一天下后仍执著长生，广征方士，投入多年炼药；丹成时听从赵高建议，让十名忠臣先试服，见他们剧烈痛苦便认定危险，处死献药者，自己没有服药而终于死去。卓齿至今仍为被选为忠臣、获准称其大王而自豪，卫斯理却看出试药实质是君主让别人承担风险，两种评价在地下长生者的故事中并存。秦王的命令间接造成十人的药物生命和方士死亡，但他本人并未得到长生，也不知道后来千年休眠的真实结果。王陵工程和历史帝国体现其组织强制力，不能在评级中无条件化为个人肉身能量或随身可召的军队。终局明确死亡，若部署只恢复最后可行动的生前君主形态，保留小说中已知后果以供其面对选择；不得把史书传说、其他宇宙帝王能力或属臣丹效叠加。演绎的冲突可以落在他对自身生命的执著、对臣下忠诚的要求和对未知试验的恐惧，而非只用统一天下的口号代替个人判断。','《活俑》回述中已死亡且未服长生药；部署恢复最后可行动的生前本人，不复建帝国','反派','延续自身统治与生命，要求臣下为君主承担风险','习惯发布命令、调集人力，并把忠诚视作理所当然','自己的安全不确定时先试人，再以强制惩罚处理失败','统治资源必须实际存在，命令造成的后果不等于个人拥有对应神力',[ab('君主组织与强制','在其统治条件下召集方士、下令试药和处死献药者','须有臣属与制度执行；终局已死，不常驻军队或不老药')],[ev('062',3309,3329,'赵高建议与试药处死'),ev('062',3338,3348,'君臣称谓与死亡殉葬')],profile='ordinary',aliases=['秦始皇（小说化回述）']))
cards.append(compact('zhao_gao','赵高（《活俑》叙述）','赵高在《活俑》中通过卓齿的回忆出现，是劝秦王不要立即服下长生药的人。药物耗费方士多年研究，但成效未知，他建议先拘捕方士、选十人试服，观察有没有变化，再决定君主是否服用。秦王采纳后，十人痛苦腹痛，献药者遭处死，秦王终究没有得到后来被证实存在的长寿效果。卓齿把未能与大王一同长生的遗憾全归罪于赵高，卫斯理却反过来认为若秦王活到现代将难以想象；这些评价不同，不能替代对实际行为的记录。卡片只依据小说中的进言和权力位置，不把“指鹿为马”等历史典故无限扩写成现实改写能力，更不能假定他早知道丹药的休眠机制而蓄意阻止长生。终局属于历史已故者，部署恢复最后可行动的生前政治人物，离开原君臣制度后影响力必须重新建立。他的演绎可围绕君主风险、试验责任和维护自身位置展开，使用谨慎话术使别人承担成本；同样必须面对建议导致的具体死亡，而不是只作为一个被古人骂的名字存在。','《活俑》回述中的历史已故人物；部署恢复最后可行动的生前形态，动机超出明确进言部分保留未定','反派','在宫廷决策中影响君主的风险选择并维持自己的位置','以审慎和试验为理由提出强制安排','君主将承担未知风险时建议把风险转给臣下和方士','谋略不能凭空知道药效，服从建议者的权力才使建议产生后果',[ab('宫廷进言','劝君主先选人试药并拘捕炼药者，影响重大决策','依赖君主采纳及宫廷权力；未证实控心、预言或个人战斗超能')],[ev('062',3309,3329,'进言的明确内容与后果'),ev('062',3331,3337,'卓齿和卫斯理对其不同评价')],profile='expert'))
save(cards)
